class ConsensusProbe(gl.Contract):
    value: str

    def __init__(self):
        pass

    @gl.public.write
    def accept_adjacent_band(self) -> str:
        def leader_fn():
            return LEADER_NOISY

        def validator_fn(leaders_res) -> bool:
            if not isinstance(leaders_res, gl.vm.Return):
                return False
            return compare_p1(leaders_res.calldata, VALIDATOR_NOISY, CONTEXT)["ok"]

        agreed = gl.vm.run_nondet_unsafe(leader_fn, validator_fn)
        if not agreed["verdict"] == "ELIGIBLE":
            raise gl.vm.UserError("EXPECTED: INVALID_STATE")
        self.value = "ACCEPTED"
        return "ACCEPTED"

    @gl.public.write
    def reject_wrong_verdict(self) -> str:
        def leader_fn():
            return LEADER_WRONG

        def validator_fn(leaders_res) -> bool:
            if not isinstance(leaders_res, gl.vm.Return):
                return False
            return compare_p1(leaders_res.calldata, VALIDATOR_HONEST, CONTEXT)["ok"]

        gl.vm.run_nondet_unsafe(leader_fn, validator_fn)
        self.value = "SHOULD_NOT_PERSIST"
        return "SHOULD_NOT_PERSIST"

    @gl.public.view
    def get_value(self) -> str:
        return self.value
